// Точки погруддя Сократа: семплінг яскравості фото
// «Socrates Louvre» (Eric Gaba, Wikimedia Commons, CC BY-SA 2.5). Формат: Int16 трійки x, y, вага×100,
// координати в межах −500…500.
const DATA = "";

export function socratesPoints() {
  const bin = atob(DATA);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Int16Array(bytes.buffer);
}
